import * as React from "react";
import { Dialog as SheetPrimitive } from "radix-ui";

import { useV4PortalContainer } from "../scope";
import { Button } from "./button";
import { Icon } from "./icon";

import { FrameScope } from "../lib/frame-context";
import { OverlayPendingContext, useDismissGuard, useOverlayPending } from "../lib/overlay-pending";
import { renderInForm, splitOverlaySections } from "../lib/overlay-sections";
import { useOwnedEscape } from "../lib/use-owned-escape";
import { cn } from "../lib/utils";

import overlay from "./overlay.module.css";

function Sheet({ ...props }: React.ComponentProps<typeof SheetPrimitive.Root>) {
  return <SheetPrimitive.Root data-slot="sheet" {...props} />;
}

function SheetTrigger({ ref, ...props }: React.ComponentProps<typeof SheetPrimitive.Trigger>) {
  return <SheetPrimitive.Trigger ref={ref} data-slot="sheet-trigger" {...props} />;
}
SheetTrigger.displayName = "SheetTrigger";

function SheetClose({
  ref,
  disabled,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Close>) {
  const pending = useOverlayPending();
  return (
    <SheetPrimitive.Close
      ref={ref}
      data-slot="sheet-close"
      disabled={disabled || pending}
      {...props}
    />
  );
}
SheetClose.displayName = "SheetClose";

function SheetPortal({ children, ...props }: React.ComponentProps<typeof SheetPrimitive.Portal>) {
  return (
    <SheetPrimitive.Portal container={useV4PortalContainer()} data-slot="sheet-portal" {...props}>
      <FrameScope framed={false}>{children}</FrameScope>
    </SheetPrimitive.Portal>
  );
}

function SheetOverlay({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Overlay>) {
  return (
    <SheetPrimitive.Overlay
      ref={ref}
      data-slot="sheet-overlay"
      className={cn("z-50", overlay.scrim, overlay.scrimSlow, className)}
      {...props}
    />
  );
}
SheetOverlay.displayName = "SheetOverlay";

const SheetLayout = ({
  head,
  scroll,
  footer
}: {
  head: React.ReactNode;
  scroll: React.ReactNode;
  footer: React.ReactNode;
}) => (
  <>
    {head && <div data-slot="sheet-head">{head}</div>}
    {scroll && (
      <div
        data-slot="sheet-scroll"
        data-scroll-fade="y"
        data-before-footer={Boolean(footer) || undefined}
      >
        {scroll}
      </div>
    )}
    {footer}
  </>
);

function SheetContent({
  className,
  children,
  side = "right",
  size = "sm",
  showCloseButton = true,
  pending = false,
  onEscapeKeyDown,
  onPointerDownOutside,
  onInteractOutside,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof SheetPrimitive.Content> & {
  side?: "top" | "right" | "bottom" | "left";
  size?: "sm" | "md" | "lg";
  showCloseButton?: boolean;
  /** While true, Escape, outside clicks and every close control are blocked, so an in-flight save cannot be abandoned. */
  pending?: boolean;
} & { ref?: React.Ref<React.ComponentRef<typeof SheetPrimitive.Content>> }) {
  const escape = useOwnedEscape(ref, onEscapeKeyDown);
  const guard = useDismissGuard(pending, {
    onEscapeKeyDown: escape.onEscapeKeyDown,
    onPointerDownOutside,
    onInteractOutside
  });
  const sections = splitOverlaySections(
    children,
    {
      header: SheetHeader,
      subheader: SheetSubheader,
      body: SheetBody,
      footer: SheetFooter
    },
    { pinHeader: true, lookThroughForm: true }
  );
  return (
    <SheetPortal>
      <SheetOverlay />
      <SheetPrimitive.Content
        ref={escape.ref}
        data-slot="sheet-content"
        data-has-close={showCloseButton || undefined}
        data-scroll-fade={sections ? undefined : "y"}
        data-sections={sections ? "" : undefined}
        data-side={side}
        data-size={size}
        className={cn(
          "fixed z-50 flex flex-col gap-4 data-[side=bottom]:inset-x-0 data-[side=bottom]:bottom-0 data-[side=bottom]:h-auto data-[side=left]:inset-y-0 data-[side=left]:left-0 data-[side=left]:h-full data-[side=left]:w-3/4 data-[side=right]:inset-y-0 data-[side=right]:right-0 data-[side=right]:h-full data-[side=right]:w-3/4 data-[side=top]:inset-x-0 data-[side=top]:top-0 data-[side=top]:h-auto",
          overlay.pop,
          overlay.sheet,
          className
        )}
        aria-busy={pending || undefined}
        {...props}
        {...guard}
      >
        <OverlayPendingContext value={pending}>
          {sections
            ? renderInForm(
                sections.form,
                "sheet-form",
                <SheetLayout
                  head={sections.pinned.length > 0 && sections.pinned}
                  scroll={sections.scroll.length > 0 && sections.scroll}
                  footer={sections.footer.length > 0 && sections.footer}
                />
              )
            : children}
          {showCloseButton && (
            <SheetPrimitive.Close data-slot="sheet-close" asChild>
              <Button variant="ghost" className={overlay.close} size="icon-sm" disabled={pending}>
                <Icon name="x" />
                <span className="sr-only">Close</span>
              </Button>
            </SheetPrimitive.Close>
          )}
        </OverlayPendingContext>
      </SheetPrimitive.Content>
    </SheetPortal>
  );
}
SheetContent.displayName = "SheetContent";

/**
 * The pinned layout for content that SheetContent cannot see: a view component that renders its own
 * header and footer, or a header wrapped in another component. header and footer are pinned and
 * children scroll between them, so pinning never depends on what the direct children are.
 */
function SheetSections({
  header,
  footer,
  children,
  className,
  ref,
  ...props
}: Omit<React.ComponentPropsWithoutRef<"div">, "children"> & {
  header?: React.ReactNode;
  footer?: React.ReactNode;
  children?: React.ReactNode;
} & { ref?: React.Ref<HTMLDivElement> }) {
  return (
    <div ref={ref} data-slot="sheet-sections" data-sections="" className={cn(className)} {...props}>
      <SheetLayout
        head={header}
        scroll={children}
        footer={footer && <div data-slot="sheet-foot">{footer}</div>}
      />
    </div>
  );
}
SheetSections.displayName = "SheetSections";

function SheetHeader({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="sheet-header"
      className={cn("flex flex-col gap-0.5 p-4", className)}
      {...props}
    />
  );
}
SheetHeader.displayName = "SheetHeader";

function SheetSubheader({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & { ref?: React.Ref<HTMLDivElement> }) {
  return <div ref={ref} data-slot="sheet-subheader" className={cn(className)} {...props} />;
}
SheetSubheader.displayName = "SheetSubheader";

function SheetBody({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & { ref?: React.Ref<HTMLDivElement> }) {
  return <div ref={ref} data-slot="sheet-body" className={cn(className)} {...props} />;
}
SheetBody.displayName = "SheetBody";

function SheetFooter({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="sheet-footer"
      className={cn("mt-auto flex flex-col gap-2 p-4", className)}
      {...props}
    />
  );
}
SheetFooter.displayName = "SheetFooter";

function SheetTitle({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Title>) {
  return (
    <SheetPrimitive.Title
      ref={ref}
      data-slot="sheet-title"
      className={cn("text-foreground", className)}
      {...props}
    />
  );
}
SheetTitle.displayName = "SheetTitle";

function SheetDescription({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Description>) {
  return (
    <SheetPrimitive.Description
      ref={ref}
      data-slot="sheet-description"
      className={cn("text-muted-foreground", className)}
      {...props}
    />
  );
}
SheetDescription.displayName = "SheetDescription";

export {
  Sheet,
  SheetBody,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetSections,
  SheetSubheader,
  SheetTitle,
  SheetTrigger
};

.scrim {
  position: fixed;
  inset: 0;
  background-color: var(--v4-scrim);
}
.scrim[data-state="open"] {
  animation: fadeIn var(--v4-duration-slow) var(--v4-ease-fade) both;
}
.scrim[data-state="closed"] {
  animation: fadeOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.pop {
  box-sizing: border-box;
  background-color: var(--v4-pop);
  color: var(--v4-ink);
  white-space: normal;
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-pop-line),
    var(--v4-shadow-pop);
  outline: none;
}
/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  display: grid;
  width: calc(100% - 2 * var(--v4-space-16));
  max-width: var(--v4-size-dialog);
  max-height: calc(100dvh - 2 * var(--v4-size-overlay-margin));
  overflow-y: auto;
  translate: -50% -50%;
}
.dialog[data-sections] {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.dialog[data-state="open"] {
  animation: dialogIn var(--v4-duration-slow) var(--v4-ease-spring-soft) both;
}
.dialog[data-state="closed"] {
  animation: dialogOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.palette {
  --v4-palette-top: clamp(var(--v4-space-48), 13vh, calc(3 * var(--v4-space-48)));
  top: var(--v4-palette-top);
  display: flex;
  flex-direction: column;
  max-width: var(--v4-size-dialog-wide);
  max-height: calc(100dvh - var(--v4-palette-top) - var(--v4-space-16));
  overflow: hidden;
  translate: -50% 0;
}
.palette [cmdk-root] {
  min-height: 0;
}
.palette [data-slot="command-scroll"] {
  flex: 0 1 auto;
  min-height: 0;
}
.palette [cmdk-item] {
  min-height: var(--v4-size-control-md);
}
.close[data-slot] {
  position: absolute;
  top: calc(
    var(--v4-dialog-pad, var(--v4-space-overlay-inset)) +
      (var(--v4-type-title-line-height) - var(--v4-size-nested-md)) / 2
  );
  inset-inline-end: calc(
    var(--v4-dialog-pad, var(--v4-space-overlay-inset)) -
      (var(--v4-size-nested-md) - var(--v4-size-icon)) / 2
  );
}
.sheet {
  --v4-sheet-from: 100% 0;
  --v4-sheet-size: var(--v4-size-sheet-sm);
}
.sheet[data-size="md"] {
  --v4-sheet-size: var(--v4-size-sheet-md);
}
.sheet[data-size="lg"] {
  --v4-sheet-size: var(--v4-size-sheet-lg);
}
.sheet[data-side="left"],
.sheet[data-side="right"] {
  max-width: min(var(--v4-sheet-size), 100vw);
}
.sheet[data-side="left"] {
  --v4-sheet-from: -100% 0;
}
.sheet[data-side="top"] {
  --v4-sheet-from: 0 -100%;
}
.sheet[data-side="bottom"] {
  --v4-sheet-from: 0 100%;
}
.sheet[data-state="open"] {
  animation: sheetIn var(--v4-duration-slow) var(--v4-ease-spring-soft) both;
}
.sheet[data-state="closed"] {
  animation: sheetOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
}
@keyframes fadeOut {
  to {
    opacity: 0;
  }
}
@keyframes dialogIn {
  from {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes dialogOut {
  to {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes sheetIn {
  from {
    translate: var(--v4-sheet-from);
  }
}
@keyframes sheetOut {
  to {
    translate: var(--v4-sheet-from);
  }
}
@media (prefers-reduced-motion: reduce) {
  .dialog[data-state="open"],
  .sheet[data-state="open"] {
    animation-name: fadeIn;
  }
  .dialog[data-state="closed"],
  .sheet[data-state="closed"] {
    animation-name: fadeOut;
  }
}
